=<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Creator Engine System Report</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    body { 
      font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; 
      background-color: #fcfcfc; 
      color: #2e403d; 
      margin: 0; 
      padding: 30px 20px; 
    }
    .container { 
      max-width: 600px; 
      margin: 0 auto; 
      background: #ffffff; 
      border-radius: 24px; 
      overflow: hidden; 
      box-shadow: 0 20px 50px rgba(0, 132, 101, 0.05); 
      border: 1px solid #e4f3ee; 
    }
    .header { 
      background: linear-gradient(135deg, #2e403d 0%, #008465 100%); 
      padding: 40px 30px; 
      text-align: center; 
      color: #ffffff; 
    }
    .header h1 { 
      margin: 0; 
      font-size: 26px; 
      font-weight: 800; 
      letter-spacing: -0.5px; 
    }
    .header p { 
      margin: 6px 0 0 0; 
      font-size: 13px; 
      color: #a3d9cb; 
      text-transform: uppercase;
      letter-spacing: 1px;
      font-weight: 600;
    }
    .content { 
      padding: 35px 30px; 
    }
    .grid { 
      display: table; 
      width: 100%; 
      table-layout: fixed; 
      margin-bottom: 25px; 
    }
    .grid-col { 
      display: table-cell; 
      width: 50%; 
      padding: 8px; 
    }
    .card { 
      background: #fbfdfc; 
      border: 1px solid #e4f3ee; 
      border-radius: 16px; 
      padding: 20px 16px; 
      text-align: center; 
      transition: all 0.2s ease;
    }
    .card-title { 
      font-size: 11px; 
      text-transform: uppercase; 
      color: #8fa8a2; 
      font-weight: 700; 
      letter-spacing: 1px; 
      margin-bottom: 8px; 
    }
    .card-value { 
      font-size: 26px; 
      font-weight: 800; 
      color: #2e403d; 
    }
    .table-container { 
      width: 100%; 
      border-collapse: collapse; 
      margin-top: 10px; 
    }
    .table-container th { 
      background: #e4f3ee; 
      color: #008465; 
      font-weight: 800; 
      font-size: 12px; 
      text-align: left; 
      padding: 12px 14px; 
      border-radius: 4px;
    }
    .table-container td { 
      padding: 14px; 
      border-bottom: 1px solid #e4f3ee; 
      font-size: 13px; 
      color: #2e403d; 
    }
    .feature-item { 
      margin-bottom: 18px; 
    }
    .feature-header {
      font-size: 13px;
      margin-bottom: 6px;
    }
    .feature-name { 
      color: #2e403d; 
      font-weight: 600; 
      float: left; 
    }
    .feature-value { 
      color: #008465; 
      font-weight: 700; 
      float: right; 
    }
    .progress-track {
      background: #e4f3ee;
      height: 6px;
      border-radius: 3px;
      overflow: hidden;
      width: 100%;
    }
    .progress-bar {
      background: #008465;
      height: 100%;
      border-radius: 3px;
    }
    .footer { 
      background: #fbfdfc; 
      padding: 25px; 
      text-align: center; 
      font-size: 11px; 
      color: #8fa8a2; 
      border-top: 1px solid #e4f3ee; 
    }
    .badge { 
      display: inline-block; 
      padding: 5px 10px; 
      font-size: 10px; 
      font-weight: 700; 
      border-radius: 8px; 
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }
    .badge-success { 
      background-color: #e4f3ee; 
      color: #008465; 
    }
    .badge-admin { 
      background-color: #2e403d; 
      color: #ffffff; 
    }
    .clearfix { 
      clear: both; 
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>Creator Engine</h1>
      <p>System Diagnostics &amp; Analytics Report</p>
    </div>
    <div class="content">
      <div class="grid">
        <div class="grid-col">
          <div class="card">
            <div class="card-title">Total Users</div>
            <div class="card-value">{{ $json.totalUsers }}</div>
          </div>
        </div>
        <div class="grid-col">
          <div class="card">
            <div class="card-title">New Signups</div>
            <div class="card-value" style="color: #008465;">+{{ $json.recentSignups }}</div>
          </div>
        </div>
      </div>
      <div class="grid" style="margin-top: -10px;">
        <div class="grid-col">
          <div class="card">
            <div class="card-title">Agent Success Rate</div>
            <div class="card-value" style="color: #008465;">
              {{ Math.round(($json.statusBreakdown.success / $json.totalRuns) * 100) }}%
            </div>
          </div>
        </div>
        <div class="grid-col">
          <div class="card">
            <div class="card-title">Credits Spent</div>
            <div class="card-value" style="color: #2e403d;">{{ $json.totalCreditsConsumed }}</div>
          </div>
        </div>
      </div>

      <!-- Section Title: Registrations -->
      <table border="0" cellpadding="0" cellspacing="0" width="100%" style="border-collapse: collapse; margin: 35px 0 20px 0;">
        <tr>
          <td style="width: 4px; background-color: #008465; border-radius: 2px;">&nbsp;</td>
          <td style="padding-left: 10px; font-size: 13px; font-weight: 800; color: #2e403d; text-transform: uppercase; letter-spacing: 1px; font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;">Recent User Registrations</td>
        </tr>
      </table>

      <table class="table-container">
        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Role</th>
          </tr>
        </thead>
        <tbody>
          {{ $json.users.map(u => `
            <tr>
              <td><strong>${u.name}</strong></td>
              <td>${u.email}</td>
              <td><span class="badge ${u.role === 'admin' ? 'badge-admin' : 'badge-success'}">${u.role}</span></td>
            </tr>
          `).join('') }}
        </tbody>
      </table>

      <!-- Section Title: Token Usage -->
      <table border="0" cellpadding="0" cellspacing="0" width="100%" style="border-collapse: collapse; margin: 35px 0 20px 0;">
        <tr>
          <td style="width: 4px; background-color: #008465; border-radius: 2px;">&nbsp;</td>
          <td style="padding-left: 10px; font-size: 13px; font-weight: 800; color: #2e403d; text-transform: uppercase; letter-spacing: 1px; font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;">Token Usage Breakdown</td>
        </tr>
      </table>

      <div style="margin-top: 15px;">
        {{
          Object.entries($json.featureBreakdown).map(([feature, amount]) => {
            const percentage = $json.totalCreditsConsumed > 0 ? Math.round((Math.abs(amount) / $json.totalCreditsConsumed) * 100) : 0;
            return `
              <div class="feature-item">
                <div class="feature-header">
                  <span class="feature-name">${feature}</span>
                  <span class="feature-value">${Math.abs(amount)} Credits (${percentage}%)</span>
                  <div class="clearfix"></div>
                </div>
                <div class="progress-track">
                  <div class="progress-bar" style="width: ${percentage}%"></div>
                </div>
              </div>
            `;
          }).join('')
        }}
      </div>
    </div>
    <div class="footer">
      This is an automated system report. To configure alert settings, visit the System Policies inside your Admin Dashboard.
    </div>
  </div>
</body>
</html>
